import type { DeepPartial, Theme } from "@types";

/**
 * Resolves a CSS variable to its actual value from the theme's cssVariables string
 */
const getCssVariableValue = (variableName: string, theme: DeepPartial<Theme>): string | null => {
  if (theme.cssVariables) {
    const regex = new RegExp(`${variableName}\\s*:\\s*([^;]+)`);
    const match = theme.cssVariables.match(regex);
    if (match?.[1]) {
      return match[1].trim();
    }
  }
  return null;
};

/**
 * Resolves a CSS variable value from a var() expression
 */
const resolveCssVariable = (value: string, theme: DeepPartial<Theme>): string => {
  if (value.startsWith("var(")) {
    const variableNameMatch = value.match(/var\((--[^)]+)\)/);
    if (variableNameMatch) {
      const variableName = variableNameMatch[1];
      const resolvedValue = getCssVariableValue(variableName, theme);
      return resolvedValue || value;
    }
  }
  return value;
};

/**
 * Converts a typography value to a number, resolving CSS variables if necessary
 */
export const resolveTypographyValue = (
  value: string | number,
  theme: DeepPartial<Theme>,
): number => {
  if (typeof value === "number") {
    return value;
  }

  const resolvedValue = resolveCssVariable(value, theme);
  const numericMatch = resolvedValue.match(/-?\d+(\.\d+)?/);

  if (numericMatch) {
    return parseFloat(numericMatch[0]);
  }

  // Fallback to 0 if we can't parse the value
  return 0;
};

/**
 * Resolves a font family value, handling CSS variables
 */
export const resolveFontFamily = (value: string, theme: DeepPartial<Theme>): string => {
  return resolveCssVariable(value, theme);
};

/**
 * Resolves typography values for Monaco editor, converting CSS variables to actual values
 */
export const resolveTypographyForMonaco = (
  typography: {
    fontSize: string | number;
    fontFamily: string;
    fontWeight: string | number;
    lineHeight: string | number;
    letterSpacing: string | number;
  },
  theme: DeepPartial<Theme>,
) => {
  return {
    fontSize: resolveTypographyValue(typography.fontSize, theme),
    fontFamily: resolveFontFamily(typography.fontFamily, theme),
    fontWeight: resolveTypographyValue(typography.fontWeight, theme).toString(),
    lineHeight: resolveTypographyValue(typography.lineHeight, theme),
    letterSpacing: resolveTypographyValue(typography.letterSpacing, theme),
  };
};
